package com.bookstore.user.entity;
import jakarta.persistence.*;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String username; @Column(nullable=false) private String password; @Column(name="full_name",nullable=false) private String fullName; @Column(nullable=false,unique=true) private String email; public User(){} public Long getId(){return id;} public String getUsername(){return username;} public String getPassword(){return password;} public String getFullName(){return fullName;} public String getEmail(){return email;} }
